head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00214.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
let acntclsDtArray = new Array();

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정)
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {

    dlt_productBusinessCompositionAcntclsDtListRes.setData([]); // 최근 3년 결산일자 조회
    dlt_productBusinessCompositionListRes.setData([]); // 제품및사업구성 조회

};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    //필수항목 체크
    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    scwin.vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 제품및 사업구성 조회
 */
scwin.search = function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    // 최근 3년 결산일자 조회
    scwin.searchStdDt();

};

/**
 * 최근 3년 결산일자 조회
 */
scwin.searchStdDt = async function() {

    dma_productBusinessCompositionAcntclsDtInfoReq.set("kisCd", scwin.vKisCd); // 기업코드
    dma_productBusinessCompositionAcntclsDtInfoReq.set("acntclsDt", scwin.vAcntclsDt); // 결산일자

    const sbmOptions = {
        id : "sbm_productBusinessCompositionAcntclsDt",
        action : "/api/listing/nice/company-status/product-business-composition-acntclsdt",
        method : "get",
        ref : "dma_productBusinessCompositionAcntclsDtInfoReq",
        target : "dlt_productBusinessCompositionAcntclsDtListRes|append",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_productBusinessCompositionAcntclsDtListRes.setJSON(res.responseJSON.body);

    scwin.setGrdTitle();

};

/**
 * 그리드 타이틀 세팅
 */
scwin.setGrdTitle = function() {

    acntclsDtArray = []; // 배열 초기화

    grd_prodBzCompst.setHeaderValue("h_TOT_AMT1", $c.stf.FormatDateEx(dlt_productBusinessCompositionAcntclsDtListRes.getCellData(0, "stdDt")));
    grd_prodBzCompst.setHeaderValue("h_TOT_AMT2", $c.stf.FormatDateEx(dlt_productBusinessCompositionAcntclsDtListRes.getCellData(1, "stdDt")));
    grd_prodBzCompst.setHeaderValue("h_TOT_AMT3", $c.stf.FormatDateEx(dlt_productBusinessCompositionAcntclsDtListRes.getCellData(2, "stdDt")));

    for (let i=0; i < 3; i++) {
        acntclsDtArray.push(dlt_productBusinessCompositionAcntclsDtListRes.getCellData(i, "stdDt"));
    }

    // 제품및 사업구성 조회
    scwin.searchProdBzCompst();

};

/**
 * 제품및 사업구성 조회
 */
scwin.searchProdBzCompst = async function() {

    dma_productBusinessCompositionInfoReq.set("kisCd", scwin.vKisCd);
    dma_productBusinessCompositionInfoReq.set("acntclsDtList", acntclsDtArray);

    const sbmOptions = {
        id : "sbm_productBusinessComposition",
        action : "/api/listing/nice/company-status/product-business-composition",
        method : "get",
        ref : "dma_productBusinessCompositionInfoReq",
        target : "dlt_productBusinessCompositionListRes|append",
        gridview : "grd_prodBzCompst",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_productBusinessCompositionListRes.setJSON(res.responseJSON.body);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_productBusinessCompositionListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "제품및사업구성",
        sheetName : "제품및사업구성"
    };

    const infoArray = {};

    grd_prodBzCompst.advancedExcelDownload(options, infoArray);

};
